import "../state.js";
import "../i18n.js";
import "./backend_client.js";

/* Chronexa Solver — Result panel.
 *
 *   SolverUI.Result.open({
 *     result:    SolveResponse,                  // per DATA_SHAPES.md
 *     mode:      "test" | "generate",
 *     school:    SchoolData,                     // the input — needed for totals
 *     onApply(newCards)                          // applied to APP.school.cards
 *     onDiscard()                                // restore previous
 *     onViewViolations(violations)               // open verification panel
 *     onClose()                                  // dismissed without action
 *   })
 *
 * Apply semantics:
 *   - Snapshot the existing APP.school.cards (deep copy).
 *   - Replace with SolveResponse.assignment mapped to the {lessonId, day, period,
 *     classroomId} card schema.
 *   - Discard restores the snapshot.
 *
 * The snapshot is owned by this module so a user can re-open and discard up
 * until they close the panel.
 */
(function (global) {
  "use strict";

  let host, dlg, refs, state;

  function el(tag, attrs, ...kids) {
    const n = document.createElement(tag);
    if (attrs) for (const k in attrs) {
      if (k === "class") n.className = attrs[k];
      else if (k.startsWith("on") && typeof attrs[k] === "function") n.addEventListener(k.slice(2), attrs[k]);
      else n.setAttribute(k, attrs[k]);
    }
    for (const c of kids) if (c != null) n.appendChild(typeof c === "string" ? document.createTextNode(c) : c);
    return n;
  }

  function fmt(n) {
    if (n == null || !isFinite(n)) return "—";
    return Number(n).toLocaleString();
  }

  function build() {
    host = el("div", { class: "csu-backdrop", role: "presentation", "aria-hidden": "true" });
    dlg = el("section", {
      class: "csu-dialog csu-result",
      role: "dialog",
      "aria-modal": "true",
      "aria-labelledby": "csu-result-title",
    });

    const title = el("h2", { class: "csu-dialog__title", id: "csu-result-title" }, "Solver finished");
    const status = el("div", { class: "csu-result__status", id: "csu-result-status" }, "");

    const hero = el("div", { class: "csu-result__hero" });
    const placed   = el("div", { class: "csu-result__tile csu-result__tile--ok"   });
    const unplaced = el("div", { class: "csu-result__tile csu-result__tile--warn" });
    const relax    = el("div", { class: "csu-result__tile" });
    const soft     = el("div", { class: "csu-result__tile" });
    hero.append(placed, unplaced, relax, soft);

    const grid = el("div", { class: "csu-result__grid", id: "csu-result-grid" });

    const apply = el("button", { type: "button", class: "chrx-btn chrx-btn--primary", onclick: doApply, id: "csu-result-apply" }, "Apply to timetable");
    const view  = el("button", { type: "button", class: "chrx-btn", onclick: doView },  "View violations");
    const disc  = el("button", { type: "button", class: "chrx-btn chrx-btn--danger", onclick: doDiscard, id: "csu-result-discard" }, "Discard");
    const close = el("button", { type: "button", class: "chrx-btn", onclick: doClose }, "Close");
    const actions = el("div", { class: "csu-dialog__actions" }, disc, view, close, apply);

    // Phase 4 / Phase 5: diagnostics + weight suggestions container.
    // Populated by renderDiagnostics() only when the solver emitted data.
    const diagSection = el("div", { class: "csu-result__diag", id: "csu-result-diag" });

    dlg.append(title, status, hero, grid, diagSection, actions);
    host.appendChild(dlg);
    document.body.appendChild(host);

    refs = { title, status, placed, unplaced, relax, soft, grid, diagSection, apply, view, disc, close };
  }

  function renderHero(result, totalLessons) {
    const s = result.stats || {};
    refs.placed.innerHTML   = "";
    refs.unplaced.innerHTML = "";
    refs.relax.innerHTML    = "";
    refs.soft.innerHTML     = "";

    refs.placed.append(
      el("div", { class: "csu-result__num" }, fmt(s.placed)),
      el("div", { class: "csu-result__lbl" }, `placed of ${fmt(totalLessons)}`),
    );
    refs.unplaced.append(
      el("div", { class: "csu-result__num" }, fmt(s.unplaced)),
      el("div", { class: "csu-result__lbl" }, "unplaced"),
    );
    refs.relax.append(
      el("div", { class: "csu-result__num" }, fmt(s.hardConflicts)),
      el("div", { class: "csu-result__lbl" }, "hard conflicts"),
    );
    refs.soft.append(
      el("div", { class: "csu-result__num" }, fmt(s.softScore)),
      el("div", { class: "csu-result__lbl" }, "soft score"),
    );
  }

  function renderPerSlotGrid(result, school) {
    refs.grid.innerHTML = "";
    const periods = (school && school.bell && school.bell.periods) || [];
    if (!periods.length) return;
    const dayNames = (global.I18N && I18N.STRINGS && I18N.STRINGS.days && I18N.STRINGS.days.en) || ["Mon","Tue","Wed","Thu","Fri","Sat"];
    const periodIdxs = periods.map(p => p.index).sort((a, b) => a - b);

    // Build a (day,period) → count of placements.
    const buckets = new Map();
    for (const a of (result.assignment || [])) {
      const k = a.day + ":" + a.period;
      buckets.set(k, (buckets.get(k) || 0) + 1);
    }
    let maxCount = 1;
    for (const v of buckets.values()) if (v > maxCount) maxCount = v;

    const header = el("div", { class: "csu-result__gridRow csu-result__gridRow--head" });
    header.appendChild(el("div", { class: "csu-result__gridCell csu-result__gridCell--day" }, ""));
    for (const p of periodIdxs) {
      header.appendChild(el("div", { class: "csu-result__gridCell csu-result__gridCell--head" }, "P" + p));
    }
    refs.grid.appendChild(header);

    for (let d = 0; d < 6; d++) {
      const row = el("div", { class: "csu-result__gridRow" });
      row.appendChild(el("div", { class: "csu-result__gridCell csu-result__gridCell--day" }, dayNames[d] || ("D" + (d + 1))));
      for (const p of periodIdxs) {
        const k = d + ":" + p;
        const n = buckets.get(k) || 0;
        const intensity = n / maxCount;
        const cell = el("div", {
          class: "csu-result__gridCell",
          title: `${dayNames[d] || ("D" + (d + 1))} · P${p} · ${n} placements`,
          style: intensity > 0 ? `background: rgba(0,100,224,${(0.10 + 0.60 * intensity).toFixed(2)});` : "",
        }, n ? String(n) : "");
        row.appendChild(cell);
      }
      refs.grid.appendChild(row);
    }
  }

  // Phase 4 / Phase 5: render solver-authored diagnostics + weight calibration
  // suggestions. These are only present when the solver emits them (unplaced > 0
  // or placed > 0 respectively). Hidden entirely when absent.
  //
  // Diagnostics explain WHY each unplaceable lesson failed, broken down by
  // FAIL code (e.g. "TEACHER_CONFLICT: 12/26").
  // Weight suggestions show which soft-constraint categories had non-zero
  // violations, letting the user see what's driving the soft score.
  function renderDiagnostics(result) {
    refs.diagSection.innerHTML = "";
    const diag = result && Array.isArray(result.diagnostics) ? result.diagnostics : [];
    const ws   = result && result.weightSuggestions ? result.weightSuggestions : null;
    const issues = result && Array.isArray(result.validationIssues) ? result.validationIssues : [];
    const warnings = issues.filter(i => i.severity === "warn" && i.msg);

    if (!diag.length && !ws && !warnings.length) {
      refs.diagSection.style.display = "none";
      return;
    }
    refs.diagSection.style.display = "";

    const wrap = (title, bodyNode) => {
      const hdr = el("div", { class: "csu-result__diagHdr" }, title);
      const box = el("details", { class: "csu-result__diagBox" }, hdr, bodyNode);
      return box;
    };

    if (warnings.length) {
      const list = el("ul", { class: "csu-result__diagList" });
      for (const w of warnings) list.appendChild(el("li", {}, "⚠  " + w.msg));
      refs.diagSection.appendChild(wrap("Input warnings (" + warnings.length + ")", list));
    }

    if (diag.length) {
      // Make raw FAIL codes (e.g. "class_conflict: 23/42") readable.
      const REASON_WORDS = {
        teacher_conflict: "teacher already teaching",
        teacher_unavailable: "teacher off that period",
        teacher_max_per_day: "teacher daily limit",
        class_conflict: "class already in another lesson",
        class_unavailable: "class off that period",
        class_max_per_day: "class daily limit",
        room_conflict: "room taken",
        room_unavailable: "room off that period",
        subject_daily_limit: "subject daily limit",
        subject_daily_min_violation: "daily-spread rule",
        class_bell_period_invalid: "outside class hours",
        fixed_slot_mismatch: "fixed-slot clash",
        required_room_type: "no room of required type",
      };
      const humanize = (reason) => (reason || "unplaceable").replace(
        /[a-z_]+/g, (m) => REASON_WORDS[m] || m.replace(/_/g, " "));

      const impossible = diag.filter(d => d.verdict === "IMPOSSIBLE");
      const contention = diag.filter(d => d.verdict !== "IMPOSSIBLE");

      // Summary: the whole point — separate "fix the file" from "try again".
      const summary = impossible.length
        ? `⛔ ${impossible.length} cannot be placed in ANY timetable — these need a file change (free the teacher, add a room, or relax a fixed slot). ` +
          (contention.length ? `The other ${contention.length} are contention (a better run may place them).` : "")
        : `✓ None are impossible — your file is feasible. These ${contention.length} are contention: the solver couldn't fit them in this run. Re-running (or accepting the best of more branches) may place them.`;
      refs.diagSection.appendChild(el("div", { class: "csu-result__diagTip" }, summary));

      const list = el("ul", { class: "csu-result__diagList" });
      // Show impossible (actionable) first, then contention. Cap at 12 visible.
      const ordered = impossible.concat(contention);
      const cap = Math.min(ordered.length, 12);
      for (let i = 0; i < cap; i++) {
        const d = ordered[i];
        const name = d.label || d.lessonId || ("lesson " + (d.lessonIdx + 1));
        const isImp = d.verdict === "IMPOSSIBLE";
        const badge = el("span", {
          class: "csu-result__diagBadge",
          style: "font-size:0.75em;font-weight:600;margin-right:6px;padding:1px 6px;border-radius:4px;" +
            (isImp ? "background:#fde2e2;color:#b42318;" : "background:#fef3c7;color:#92400e;"),
        }, isImp ? "FIX FILE" : "CONTENTION");
        list.appendChild(el("li", {},
          badge,
          el("strong", {}, name),
          el("br"),
          el("span", { class: "csu-result__diagReason" }, humanize(d.reason)),
        ));
      }
      if (ordered.length > cap) {
        list.appendChild(el("li", { class: "csu-result__diagMore" },
          `…and ${ordered.length - cap} more. Open "View violations" for the full list.`));
      }
      refs.diagSection.appendChild(wrap("Unplaceable lessons (" + diag.length + ")", list));
    }

    if (ws) {
      const keys = Object.keys(ws).sort((a, b) => ws[b] - ws[a]);
      if (keys.length) {
        const list = el("ul", { class: "csu-result__diagList" });
        for (const k of keys) {
          const v = ws[k];
          const label = k.replace(/([A-Z])/g, " $1").replace(/^./, (c) => c.toUpperCase()).trim();
          list.appendChild(el("li", {},
            el("strong", {}, label),
            el("span", { class: "csu-result__diagReason" }, " — " + Number(v).toLocaleString() + " penalty points"),
          ));
        }
        const tip = el("div", { class: "csu-result__diagTip" },
          "These are the largest contributors to your soft score. Increasing the corresponding weight in Solver Parameters will prioritize them in the next run.");
        refs.diagSection.appendChild(wrap("Soft score breakdown", list));
        refs.diagSection.lastChild.appendChild(tip);
      }
    }
  }

  function assignmentToCards(assignment) {
    if (!Array.isArray(assignment)) return [];
    const out = [];
    for (const a of assignment) {
      out.push({
        lessonId: a.lessonId,
        day: a.day,
        period: a.period,
        classroomId: a.classroomId || null,
      });
    }
    return out;
  }

  function applyImmediately() {
    if (!state) return;
    const newCards = assignmentToCards(state.result.assignment);
    if (state.school && !state.snapshot) {
      state.snapshot = Array.isArray(state.school.cards) ? state.school.cards.slice() : [];
    }
    if (state.school) state.school.cards = newCards;
    state.applied = true;
    state.discarded = false;
    refs.apply.disabled = true;
    refs.disc.disabled = false;
    refs.status.textContent = "Applied to timetable.";
    refs.status.style.color = "var(--chrx-green)";
    // Force the editor (and pending strip) to re-render against the new
    // school.cards. Without this the grid stays empty and the pending
    // strip stays full even though the data is now in place.
    try {
      const editorRoot = document.querySelector(".chrx-editor");
      if (editorRoot && global.Editor && global.Editor.render) global.Editor.render(editorRoot);
      const pendRoot = document.querySelector(".chrx-pending-strip");
      if (pendRoot && global.PendingStrip && global.PendingStrip.render) global.PendingStrip.render(pendRoot);
    } catch (e) { console.warn("[result_panel] post-apply re-render failed", e); }
    // Snapshot the freshly applied timetable immediately (AutoSave listens).
    try { window.dispatchEvent(new CustomEvent("app:solve-applied")); } catch {}
    if (state.onApply) try { state.onApply(newCards); } catch (e) { console.error(e); }
  }
  function isDestructiveApply() {
    if (!state || !state.school) return false;
    const have = (state.school.cards && state.school.cards.length) || 0;
    const newLen = (state.result && state.result.assignment && state.result.assignment.length) || 0;
    return have > 0 && newLen < have;
  }
  function confirmDestructiveApply() {
    if (document.getElementById("chrx-apply-confirm")) return;
    const have = state.school.cards.length;
    const newLen = state.result.assignment.length;
    const lost = have - newLen;
    const hard = (state.result.stats && state.result.stats.hardConflicts) || 0;
    const overlay = document.createElement("div");
    overlay.id = "chrx-apply-confirm";
    overlay.style.cssText = "position:fixed;inset:0;background:rgba(15,23,42,.55);display:flex;align-items:center;justify-content:center;z-index:10001;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;";
    overlay.innerHTML = ''
      + '<div role="alertdialog" aria-modal="true" style="background:#fff;border-radius:14px;box-shadow:0 24px 64px rgba(15,23,42,.30);padding:24px 26px;max-width:480px;width:calc(100% - 32px);">'
      +   '<div style="font-size:32px;line-height:1;margin-bottom:8px;">⚠️</div>'
      +   '<h2 style="font-size:18px;font-weight:700;color:#9f1239;margin:0 0 8px;">Replace your timetable?</h2>'
      +   `<p style="font-size:13px;line-height:1.55;color:#475569;margin:0 0 16px;">This solver run produced <strong>${newLen}</strong> placements, but your timetable currently has <strong>${have}</strong> placed cards. Applying will lose <strong>${lost}</strong> existing card${lost === 1 ? '' : 's'}` + (hard > 0 ? ` and the new layout has <strong>${hard} hard conflict${hard === 1 ? '' : 's'}</strong>` : '') + `.</p>`
      +   '<p style="font-size:13px;line-height:1.55;color:#475569;margin:0 0 18px;">Click Discard to keep your original timetable, or confirm to replace it anyway.</p>'
      +   '<div style="display:flex;gap:8px;justify-content:flex-end;">'
      +     '<button type="button" data-cancel style="background:#fff;border:1px solid #cbd5e1;color:#0f172a;padding:8px 14px;border-radius:7px;cursor:pointer;font-size:13px;font-weight:500;">Cancel</button>'
      +     '<button type="button" data-confirm style="background:#be123c;border:0;color:#fff;padding:8px 16px;border-radius:7px;cursor:pointer;font-size:13px;font-weight:600;">Replace anyway</button>'
      +   '</div>'
      + '</div>';
    document.body.appendChild(overlay);
    overlay.querySelector("[data-cancel]").focus();
    overlay.addEventListener("click", e => { if (e.target === overlay) overlay.remove(); });
    overlay.querySelector("[data-cancel]").onclick = () => overlay.remove();
    overlay.querySelector("[data-confirm]").onclick = () => { overlay.remove(); applyImmediately(); };
  }
  function doApply() {
    if (!state) return;
    if (isDestructiveApply()) { confirmDestructiveApply(); return; }
    applyImmediately();
  }
  function doDiscard() {
    if (!state) return;
    if (state.school && state.snapshot != null) {
      state.school.cards = state.snapshot;
      state.snapshot = null;
    }
    state.discarded = true;
    refs.apply.disabled = false;
    refs.disc.disabled = true;
    refs.status.textContent = "Discarded — your previous timetable is restored.";
    refs.status.style.color = "var(--chrx-orange)";
    if (state.onDiscard) try { state.onDiscard(); } catch (e) { console.error(e); }
  }
  function doView() {
    if (!state) return;
    const v = (state.result && state.result.violations) || [];
    // Auto-apply on view-violations too (same intent as close).
    if (canAutoApply()) doApply();
    close();
    if (state.onViewViolations) try { state.onViewViolations(v); } catch (e) { console.error(e); }
  }
  function canAutoApply() {
    if (!state) return false;
    if (state.mode === "test") return false;
    if (state.applied || state.discarded) return false;
    const r = state.result;
    if (!r) return false;
    const a = r.assignment;
    if (!Array.isArray(a) || a.length === 0) return false;
    // INFEASIBLE with zero placements — never auto-apply.
    if (r.status === "INFEASIBLE" && a.length === 0) return false;
    // scrubbedConflicts = actual constraint violations in the placed
    // schedule (teacher overlaps, class overlaps, etc.). If any exist,
    // block auto-apply. Note: hardConflicts in the solver output counts
    // UNPLACED lessons, not violations in placed cards.
    const scrubbed = (r.stats && r.stats.scrubbedConflicts) || 0;
    if (scrubbed > 0) return false;
    // TIMEOUT is the *normal* outcome for medium-to-large schools. The solver
    // always uses its full time budget and returns the best result found.
    // Auto-apply if the result placed ≥ 90% of cards.
    const placed = (r.stats && r.stats.placed) || a.length;
    const unplaced = (r.stats && r.stats.unplaced) || 0;
    const total = placed + unplaced;
    if (total > 0 && placed / total < 0.90) return false;
    // Don't silently overwrite a working timetable with a much smaller one
    // (protect against solver regression). Threshold: result must have at
    // least 85% of the existing card count.
    const before = (state.school && state.school.cards && state.school.cards.length) || 0;
    if (before > 0 && a.length < before * 0.85) return false;
    return true;
  }
  function doClose() {
    // Implicit-apply: if the solver produced placements and the user
    // didn't explicitly Discard, treat Close as "keep these cards" so
    // a successful run isn't silently thrown away.
    if (canAutoApply()) doApply();
    close();
    if (state && state.onClose) try { state.onClose(); } catch (e) { console.error(e); }
    state = null;
  }

  function open(opts) {
    if (!host) build();
    state = {
      result: opts.result || { stats: {}, assignment: [], violations: [] },
      school: opts.school || null,
      mode:   opts.mode || "generate",
      onApply: opts.onApply,
      onDiscard: opts.onDiscard,
      onViewViolations: opts.onViewViolations,
      onClose: opts.onClose,
      snapshot: null,
    };
    const status = state.result.status || "DONE";
    // Hero denominator should be total expected cards (lessons × periodsPerWeek),
    // not lesson count — a single lesson can spawn many cards per week.
    let expectedCards = 0;
    if (state.school && state.school.lessons) {
      for (const l of state.school.lessons) {
        expectedCards += Math.max(1, (l.periodsPerWeek || 1));
      }
    }
    const placedNum  = (state.result.stats && state.result.stats.placed)   || 0;
    const unplacedNm = (state.result.stats && state.result.stats.unplaced) || 0;
    const totalLessons = expectedCards || (placedNum + unplacedNm);
    refs.title.textContent = state.mode === "test" ? "Test finished" : "Generator finished";
    refs.status.textContent = `${status} · ${(state.result.stats && state.result.stats.durationMs) ? Math.round(state.result.stats.durationMs / 1000) + "s" : ""}`;
    refs.status.style.color = (status === "OPTIMAL" || status === "FEASIBLE") ? "var(--chrx-green)" : "var(--chrx-orange)";
    refs.apply.disabled = state.mode === "test";
    refs.disc.disabled = true;
    renderHero(state.result, totalLessons);
    renderPerSlotGrid(state.result, state.school);
    renderDiagnostics(state.result);

    // De-emphasize Apply when the run is destructive (TIMEOUT, hard conflicts,
    // or strictly fewer cards than the current school). The confirmation
    // dialog catches actual clicks; visual styling helps prevent the click.
    const hardN = (state.result.stats && state.result.stats.hardConflicts) || 0;
    const bad = (status === "TIMEOUT" || status === "INFEASIBLE" || hardN > 0 || isDestructiveApply());
    if (refs.apply) {
      refs.apply.classList.toggle("is-warning", bad);
      refs.apply.style.background = bad ? "#fff" : "";
      refs.apply.style.color      = bad ? "#9f1239" : "";
      refs.apply.style.border     = bad ? "1px solid #f43f5e" : "";
    }

    host.classList.add("is-open");
    host.setAttribute("aria-hidden", "false");
    // Default focus to Close on dangerous results (Discard is disabled until
    // something is applied). For clean runs, focus Apply so Enter ships it.
    requestAnimationFrame(() => {
      const target = bad ? refs.close : (refs.apply && !refs.apply.disabled ? refs.apply : refs.close);
      if (target && typeof target.focus === "function") target.focus();
    });
  }
  function close() {
    if (!host) return;
    host.classList.remove("is-open");
    host.setAttribute("aria-hidden", "true");
  }

  global.SolverUI = global.SolverUI || {};
  global.SolverUI.Result = { open, close };
})(typeof window !== "undefined" ? window : globalThis);
